// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Art history starts with learning to look closely. Artists use a shared visual language.","blocks":[{"t":"key","text":"The elements of art are the building blocks: line, shape, form (3D), space, color, value (lightness and darkness) and texture."},{"t":"p","text":"The principles of design describe how elements are arranged: balance (symmetrical or asymmetrical), contrast, emphasis (focal point), movement, rhythm and pattern, proportion and unity."},{"t":"p","text":"Color basics: primary colors (red, yellow, blue), secondary colors (orange, green, violet), and complementary colors (opposites on the color wheel, like red and green) create strong contrast. Warm colors feel energetic; cool colors feel calm."}]},{"say":"Analyzing art means describing what you see, then interpreting what it means and why it was made.","blocks":[{"t":"key","text":"A four-step method: Describe (what do you see?), Analyze (how are the elements and principles used?), Interpret (what does it mean or express?), and Judge or contextualize (why was it made, and is it successful?)."},{"t":"p","text":"Context matters: who made it, when, where, for whom (the patron), and for what purpose (religious, political, personal)."},{"t":"p","text":"Iconography is the study of symbols in art. For example, a skull in a still life often symbolizes death (a memento mori), and a dove often symbolizes peace or the Holy Spirit."},{"t":"ex","problem":"A portrait shows a king on a rearing horse with a stormy sky. Interpret it.","steps":["The rearing horse and dramatic sky create power and movement"],"answer":"The artist portrays the king as heroic and in control, likely to glorify his rule"}]}],[{"say":"Art has existed as long as humans. Ancient civilizations created works that still amaze us.","blocks":[{"t":"list","items":["Prehistoric: cave paintings at Lascaux show animals; the Venus of Willendorf is an early sculpture.","Egyptian: art served religion and the afterlife. Figures follow strict conventions (heads and legs in profile, eyes and shoulders facing forward). Pyramids and the Great Sphinx served pharaohs.","Greek: idealized human forms, balance and proportion. Contrapposto (weight shifted to one leg) made statues look natural. The Parthenon used the Doric order.","Roman: realistic portrait busts, engineering marvels (arches, concrete, the Colosseum and the Pantheon dome)."]},{"t":"key","text":"Greek art emphasized idealism (perfect beauty), while Roman portraiture emphasized realism (wrinkles and all)."}]},{"say":"In the Middle Ages, most art in Europe served the Church, telling religious stories to people who often couldn't read.","blocks":[{"t":"list","items":["Byzantine art: shimmering gold mosaics and icons with flat, spiritual figures (Hagia Sophia).","Islamic art: geometric patterns, calligraphy and arabesques, often avoiding human figures in religious spaces (the Alhambra, the Dome of the Rock).","Romanesque architecture: thick walls, rounded arches, small windows.","Gothic architecture: pointed arches, ribbed vaults, flying buttresses and huge stained-glass windows that filled cathedrals with light (Notre-Dame, Chartres)."]},{"t":"key","text":"Flying buttresses let Gothic cathedrals have taller, thinner walls and large windows, symbolizing heavenly light."},{"t":"p","text":"Illuminated manuscripts were handwritten books decorated with gold and color."}]}],[{"say":"The Renaissance revived classical ideas and transformed art with realism and perspective.","blocks":[{"t":"key","text":"Linear perspective (developed by Brunelleschi) uses a vanishing point to create the illusion of depth on a flat surface."},{"t":"list","items":["Leonardo da Vinci: Mona Lisa (sfumato, soft blending), The Last Supper.","Michelangelo: the Sistine Chapel ceiling, the statue of David.","Raphael: The School of Athens, with balanced composition and classical figures.","Northern Renaissance: Jan van Eyck's detailed oil paintings (Arnolfini Portrait), Albrecht Dürer's prints."]},{"t":"p","text":"Humanism inspired artists to depict realistic human anatomy and emotion. Wealthy patrons like the Medici family funded art."}]},{"say":"After the Renaissance, art became dramatic, then orderly, then emotional, reflecting a changing Europe.","blocks":[{"t":"list","items":["Baroque (1600s): drama, movement and strong contrasts of light and dark (chiaroscuro and tenebrism). Caravaggio, Bernini's sculptures, Rembrandt, Velázquez (Las Meninas).","Neoclassicism (late 1700s): a return to Greek and Roman order and moral seriousness, linked to the Enlightenment and revolutions (Jacques-Louis David).","Romanticism (early 1800s): emotion, nature's power, imagination and the sublime (Goya, Delacroix's Liberty Leading the People, Turner, Friedrich)."]},{"t":"key","text":"Chiaroscuro is the strong contrast between light and dark used to create drama and three-dimensional form."}]}],[{"say":"In the late 1800s, artists broke from tradition to capture light, moments and personal visions.","blocks":[{"t":"key","text":"Impressionists (Monet, Renoir, Degas, Morisot) painted outdoors (en plein air) with quick, visible brushstrokes to capture changing light and everyday modern life."},{"t":"p","text":"Post-Impressionists went further in personal directions:"},{"t":"list","items":["Van Gogh: bold color and expressive, swirling brushstrokes (The Starry Night).","Cézanne: geometric structure, influencing Cubism.","Seurat: pointillism, painting with tiny dots of color.","Gauguin: flat areas of bold color and symbolism."]},{"t":"p","text":"Photography and new paint tubes influenced these changes."},{"t":"tip","text":"Stand close to an Impressionist painting and you see separate brushstrokes; step back and they blend into shimmering light. That effect was the point."}]},{"say":"The 20th century exploded with new movements that questioned what art could be.","blocks":[{"t":"list","items":["Fauvism: wild, bold colors (Matisse).","Cubism: breaking objects into geometric shapes seen from multiple viewpoints (Picasso, Braque).","Surrealism: dreamlike, irrational imagery from the unconscious (Dalí, Magritte, Frida Kahlo is often linked).","Abstract Expressionism: large, emotional abstract works (Pollock's drip paintings, Rothko's color fields).","Pop Art: images from advertising and popular culture (Warhol, Lichtenstein)."]},{"t":"key","text":"Many modern artists rejected realistic representation to express ideas, emotions or new ways of seeing."},{"t":"p","text":"Contemporary art includes installation, performance, video and digital art, and often addresses identity, politics and society."}]}]];
export default text;
